onKeyDown (event) => {
              if (
                event.target === event.currentTarget &&
                (event.key === 'Enter' || event.key === ' ')
              ) {
                event.preventDefault();
                toggle();
              }
            }

onSubmit handleSubmit(({ cdsid, requestReference }) => {
        reset();
        setLastUser(cdsid);
        onSave(cdsid, requestReference);
      })

